-- ============================================================
--  EVAD — Bibliothèque partagée : solutions & indicateurs (source de vérité)
--  À exécuter dans le projet Supabase de PROD (lmhhrccmgebztioesmik)
--  → SQL Editor. Généré automatiquement depuis le code (v102).
--
--  L'app lit la bibliothèque au chargement ; si la base est injoignable,
--  elle retombe sur la version embarquée dans le JS. Pour modifier la
--  bibliothèque : Table Editor (les lignes actif=false sont ignorées).
--  Lecture publique, AUCUNE écriture par le front (édition via dashboard).
-- ============================================================

-- Si l'ancienne version « catalogue_ » a déjà été exécutée, on renomme les
-- tables (les données déjà saisies sont conservées). Sans effet sinon.
alter table if exists public.catalogue_solutions rename to biblio_solutions;
alter table if exists public.catalogue_indicateurs rename to biblio_indicateurs;

create table if not exists public.biblio_solutions (
  id          text primary key,
  nom         text not null unique,       -- clé fonctionnelle (référencée partout)
  cat         text,                       -- catégorie (eau, electricite, …)
  cplx        text,                       -- facile | moyen | expert
  img         text,                       -- emoji
  photo       text,                       -- URL illustration
  description text,
  impact      text,                       -- résumé d'impact (affiché en liste)
  budget      text,
  co2         numeric,                    -- tCO2/an évitées
  graines     int default 50,             -- récompense de la quête
  avantages   jsonb,                      -- liste de points forts
  indicateurs_libres jsonb,               -- indicateurs texte (repli)
  esrs        jsonb,                      -- ex. ["ESRS E3"]
  esrs_detail text,
  lieux       jsonb,                      -- types de lieux compatibles
  quete_titre text,                       -- la quête portée par la solution
  quete_duree text,
  quete_nb    text,
  quete_impact text,
  ordre       int,
  actif       boolean default true,
  created_at  timestamptz default now(),
  updated_at  timestamptz default now()
);

create table if not exists public.biblio_indicateurs (
  id          text primary key,           -- id ICI (ex. eco_co2)
  nom         text not null,
  livre       text,                       -- ecologie | social | economie_locale
  unite       text,
  point0      numeric,                    -- valeur de départ (T0)
  point100    numeric,                    -- référence « excellent » (sous-score 100)
  poids       numeric default 1,
  description text,
  photo       text,                       -- URL illustration
  solution_noms jsonb,                    -- noms des solutions qui portent cet ICI
  odd         jsonb,                      -- correspondances ODD (numéros)
  esrs        jsonb,                      -- correspondances ESRS (codes)
  vsme        jsonb,                      -- correspondances VSME (libellés)
  ordre       int,
  actif       boolean default true,
  created_at  timestamptz default now(),
  updated_at  timestamptz default now()
);

-- Colonne ajoutée après coup (sans effet si déjà présente).
alter table public.biblio_indicateurs add column if not exists photo text;

alter table public.biblio_solutions enable row level security;
alter table public.biblio_indicateurs enable row level security;

-- Lecture publique ; pas de policy d'écriture : le front ne modifie JAMAIS la
-- bibliothèque (édition via le dashboard Supabase, qui contourne la RLS).
drop policy if exists "catalogue_solutions_select" on public.biblio_solutions;
drop policy if exists "catalogue_indicateurs_select" on public.biblio_indicateurs;
drop policy if exists "biblio_solutions_select" on public.biblio_solutions;
create policy "biblio_solutions_select" on public.biblio_solutions for select using (true);
drop policy if exists "biblio_indicateurs_select" on public.biblio_indicateurs;
create policy "biblio_indicateurs_select" on public.biblio_indicateurs for select using (true);

-- ── Seed : bibliothèque actuelle (rejouable : upsert par id) ──
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('recuperation-eau-de-pluie','Récupération eau de pluie','eau','facile','💧','https://images.unsplash.com/photo-1525498128493-380d1990a112?w=800&q=80&auto=format&fit=crop','Système de collecte des eaux pluviales via les gouttières, stockées dans une cuve enterrée ou aérienne (500 à 5 000 L). L''eau récupérée couvre l''arrosage, les sanitaires et le nettoyage, réduisant la consommation d''eau potable de 40 à 60%. Solution simple, sans permis, amortie en 2 à 4 ans selon l''usage.','−18 000 L/an','800–3 500 €',0,50,'["Économie jusqu''à 18 000 L d''eau potable par an","ROI en 2–4 ans, entretien quasi nul","Compatible avec toute toiture et tout type de lieu"]'::jsonb,'["Eau économisée L/an","Autonomie eau %"]'::jsonb,'["ESRS E3"]'::jsonb,'Réduit la consommation d''eau et les rejets, indicateur eau GRI 303.','["ferme","jardin","ecolieu","habitat","tiers","cafe","epicerie","fablab","repair","ressourcerie","coworking","incubateur","ecole","autre"]'::jsonb,'Installer une cuve de récupération','1 journée','3–5 pers.','+8 pts eau · −18 000 L/an',1)
