  values ('panneaux-solaires-pv','Panneaux solaires PV','electricite','moyen','☀️','https://images.unsplash.com/photo-1508514177221-188b1cf16e9d?w=800&q=80&auto=format&fit=crop','Installation de modules photovoltaïques en toiture pour produire de l''électricité directement consommée sur site (autoconsommation) ou réinjectée sur le réseau. Une installation de 6 kWc produit environ 6 000 kWh/an en région tempérée, couvrant 30 à 80 % des besoins selon le profil de consommation. ROI entre 7 et 10 ans, durée de vie 25 à 30 ans.','3 500 kWh/an','6 000–18 000 € (installation 6 kWc)',0.9,90,'["Jusqu''à 80 % d''autonomie électrique en journée","−900 kgCO₂/an évités dès la première année","Valorisable en ESRS E1 pour tout rapport CSRD"]'::jsonb,'["Énergie produite kWh/an","CO₂ évité kgCO2/an"]'::jsonb,'["ESRS E1"]'::jsonb,'Réduction directe des émissions Scope 2, contribue à la trajectoire Net-Zero SBTi.','["ferme","ecolieu","habitat","tiers","fablab","coworking","incubateur","cafe","epicerie","repair","ecole"]'::jsonb,'Chantier participatif d''installation solaire','2 jours','6–10 pers.','+15 pts énergie · −900 kgCO₂/an',4)
