  values ('potager-en-buttes','Potager en buttes','alimentaire','facile','🌻','https://images.unsplash.com/photo-1592419044706-39796d40f98c?w=800&q=80&auto=format&fit=crop','Technique de culture sur buttes de bois en décomposition (bois raméal fragmenté, bûches, compost) inspirée de la méthode Hügelkultur. Le bois stocke l''humidité et libère des nutriments sur plusieurs années, réduisant l''arrosage de 60 à 70 %. Idéal pour démarrer rapidement avec peu de moyens sur un sol pauvre.','~80 kg/an','100–400 € (bois récupéré + semences)',0.2,35,'["Arrosage réduit de 60–70 % grâce au bois","Valorise les déchets de bois du site","Mise en place en une journée, productif dès la 1ère saison"]'::jsonb,'["Production alimentaire kg/an","Eau économisée L/an"]'::jsonb,'["ESRS E3","ESRS S3"]'::jsonb,'Réduction de l''irrigation (E3) · production alimentaire locale pour la communauté (S3).','["ferme","jardin","ecolieu","tiers","habitat","ecole"]'::jsonb,'Construire les premières buttes maraîchères','1 journée','3–6 pers.','+6 pts alimentation · −5 000 L eau/an',10)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
