  values ('compostage-partage','Compostage partagé','dechets','facile','🌍','https://images.unsplash.com/photo-1591857177580-dc82b9ac4e1e?w=800&q=80&auto=format&fit=crop','Point de collecte collectif des biodéchets (épluchures, marc de café, restes alimentaires) transformés en compost par décomposition aérobie sur 3 à 6 mois. Détourne 500 à 800 kg de déchets organiques par an de la poubelle grise, produisant 100 à 150 kg de compost mûr utilisable au jardin. Fort levier de sensibilisation et de lien social.','−500 kg déchets/an','200–800 € (composteur collectif + formation)',0.3,30,'["500–800 kg de déchets organiques valorisés par an","100–150 kg de compost gratuit pour le jardin","Action fédératrice : implique toute la communauté du lieu"]'::jsonb,'["Déchets détournés kg/an","Compost produit kg/an"]'::jsonb,'["ESRS E5","ESRS S3"]'::jsonb,'Détournement déchets organiques (E5) · mobilisation de la communauté locale (S3).','["ferme","jardin","ecolieu","tiers","cafe","epicerie","ecole","habitat","coworking","fablab","ressourcerie"]'::jsonb,'Lancer le compostage collectif','2h + suivi mensuel','2–5 pers.','+8 pts déchets · 500 kg/an valorisés',11)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
