  values ('haie-champetre','Haie champêtre','biodiversite','facile','🌳','https://images.unsplash.com/photo-1490750967868-88df5691cc68?w=800&q=80&auto=format&fit=crop','Plantation d''une haie multi-espèces avec des essences locales (cornouiller, prunellier, aubépine, sureau…) qui accueille nidification, abri et alimentation pour la faune sauvage. Séquestre du carbone, protège des vents dominants et réduit l''érosion des sols. Entretien minimal une fois les arbustes établis après 2 à 3 ans.','+12 espèces','15–40 €/m linéaire (plants + pose)',0.5,45,'["+12 espèces animales accueillies dès la 2ème année","Séquestre 200–500 kg de CO₂/an sur 50 m linéaires","Brise-vent réduisant les besoins de chauffage de 5–10 %"]'::jsonb,'["Score biodiversité","Espèces favorisées nb"]'::jsonb,'["ESRS E4"]'::jsonb,'Indicateur direct ESRS E4, restauration d''écosystèmes, séquestration carbone.','["ferme","jardin","ecolieu","habitat"]'::jsonb,'Planter la haie champêtre','1 journée','4–8 pers.','+15 pts biodiversité · +12 espèces',12)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
