  values ('mare-ecologique','Mare écologique','biodiversite','moyen','🐸','https://images.unsplash.com/photo-1473621038190-1f1e0fe63ee9?w=800&q=80&auto=format&fit=crop','Création d''un plan d''eau permanent ou temporaire avec berges en pente douce et végétation aquatique locale. Habitat essentiel pour les amphibiens, libellules, oiseaux et insectes pollinisateurs. La mare joue aussi un rôle de régulation hydraulique et de filtration naturelle des eaux de ruissellement du site.','+amphibiens & insectes','800–3 000 € (terrassement + végétalisation)',0.1,60,'["Habitat pour 8+ espèces d''amphibiens et d''insectes","Régule les eaux de ruissellement du site","Aucun entretien après la 1ère saison si bien conçue"]'::jsonb,'["Score biodiversité","Espèces favorisées nb"]'::jsonb,'["ESRS E4","ESRS E3"]'::jsonb,'Restauration d''habitats aquatiques (E4) · gestion naturelle des eaux (E3).','["ferme","jardin","ecolieu","habitat"]'::jsonb,'Creuser et aménager la mare','2 journées','4–6 pers.','+18 pts biodiversité · habitat pour 8+ espèces',13)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('repair-cafe','Repair café','social','facile','🔧','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80&auto=format&fit=crop','Événement mensuel ouvert à tous où des bénévoles compétents aident les habitants à réparer leurs appareils électroménagers, vêtements, vélos et objets du quotidien. Chaque objet réparé évite en moyenne 4 kg de CO₂. Crée un fort lien social intergénérationnel et valorise les savoir-faire locaux tout en réduisant les déchets.','~200 objets réparés/an','0–500 € (outillage de base)',0.8,35,'["200 objets réparés/an · −800 kgCO₂ évités","Aucun investissement initial, juste de l''espace et des bénévoles","Mobilise 20–50 personnes/mois dans la communauté"]'::jsonb,'["Nb personnes impliquées","Événements collectifs nb/mois"]'::jsonb,'["ESRS E5","ESRS S1","ESRS S3"]'::jsonb,'Économie circulaire (E5) · formation & montée en compétences (S1) · cohésion communautaire (S3).','["fablab","repair","ressourcerie","tiers","cafe","ecole"]'::jsonb,'Organiser le premier Repair Café','1 après-midi/mois','3–8 pers.','+10 pts social · 200 objets/an · −800 kgCO₂',14)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
