  values ('amap-circuit-court','AMAP circuit court','social','facile','🥕','https://images.unsplash.com/photo-1488459716781-31db52582fe9?w=800&q=80&auto=format&fit=crop','Association pour le Maintien de l''Agriculture Paysanne : contrat direct entre le lieu et un ou plusieurs agriculteurs locaux qui livrent chaque semaine un panier de saison. Supprime les intermédiaires, garantit un revenu fixe à l''agriculteur et réduit de 60 à 80 % les émissions liées au transport alimentaire. Renforce l''ancrage territorial et la résilience alimentaire du lieu.','90% local','0 € (rémunéré par les adhérents)',0.6,30,'["90 % de l''alimentation d''origine locale et traçable","−60 % d''émissions CO₂ liées au transport des aliments","Garantit un revenu équitable à l''agriculteur partenaire"]'::jsonb,'["Part circuits courts %","Autonomie alimentaire %"]'::jsonb,'["ESRS S2","ESRS S3"]'::jsonb,'Chaîne de valeur locale et équitable (S2) · accès à l''alimentation saine pour la communauté (S3).','["cafe","epicerie","tiers","ecole","coworking","ecolieu","ferme"]'::jsonb,'Monter le partenariat AMAP','2 réunions','2–4 pers.','+12 pts social · 90% approvisionnement local',15)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('toiture-murs-vegetalises','Toiture & murs végétalisés','adaptation','moyen','🪴',null,'Couvrir toits et murs d''une couche végétale (substrat léger + plantes résistantes à la sécheresse) qui isole du chaud comme du froid. La surface abaisse sa température de plusieurs degrés, retient 50 à 80 % des eaux de pluie et crée un refuge de biodiversité. Réduit les besoins de climatisation lors des canicules de plus en plus fréquentes.','−3 à −5 °C en toiture','60–150 €/m²',0.3,80,'["Abaisse la température intérieure de 2 à 4 °C en été","Retient 50–80 % des eaux de pluie, limite le ruissellement","Double l''isolation et accueille la biodiversité"]'::jsonb,'["Surface végétalisée m²","Température de surface évitée °C"]'::jsonb,'["ESRS E1","ESRS E4"]'::jsonb,'Adaptation au changement climatique (E1) et contribution à la biodiversité (E4).','["ecolieu","habitat","tiers","fablab","coworking","incubateur","cafe","epicerie","ecole","autre"]'::jsonb,'Installer une toiture végétalisée','2 week-ends','4–8 pers.','+10 pts adaptation · −3 °C en toiture',16)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('canopee-ilots-de-fraicheur','Canopée & îlots de fraîcheur','adaptation','moyen','🌳',null,'Planter des arbres et arbustes d''ombrage (essences locales adaptées à la sécheresse) pour créer des îlots de fraîcheur. Un arbre mature rafraîchit l''air ambiant par évapotranspiration et par son ombre, jusqu''à 2 à 4 °C ressentis sous le houppier. Protège les espaces extérieurs, les façades et les usagers pendant les vagues de chaleur.','−2 à −4 °C ressentis','30–120 €/arbre',0.6,70,'["Jusqu''à −4 °C ressentis sous les arbres","Stocke du carbone et abrite la biodiversité","Ombre naturelle qui limite la surchauffe des bâtiments"]'::jsonb,'["Arbres plantés","Surface ombragée m²"]'::jsonb,'["ESRS E1","ESRS E4"]'::jsonb,'Adaptation aux fortes chaleurs (E1) et renforcement des écosystèmes (E4).','["ferme","ecolieu","habitat","jardin","tiers","ecole","autre"]'::jsonb,'Planter des arbres d''ombrage','1 journée','5–12 pers.','+9 pts adaptation · îlot de fraîcheur',17)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('ombrieres-pergolas-bioclimatiques','Ombrières & pergolas bioclimatiques','adaptation','facile','⛱️',null,'Installer des structures d''ombrage (pergolas, voiles, ombrières), végétalisées ou couplées à des panneaux solaires, sur les zones exposées : terrasses, façades sud, parkings. Elles bloquent le rayonnement direct, abaissent la température des surfaces et des espaces de vie, et peuvent produire de l''électricité (ombrière photovoltaïque).','−30 à −50 % de soleil direct','150–500 €/m²',0.2,50,'["Réduit de 30 à 50 % le rayonnement solaire direct","Protège façades et terrasses de la surchauffe","Cumulable avec du solaire en ombrière photovoltaïque"]'::jsonb,'["Surface ombragée m²","Énergie solaire produite kWh/an"]'::jsonb,'["ESRS E1"]'::jsonb,'Protection solaire passive, adaptation au réchauffement (E1).','["ecolieu","habitat","tiers","fablab","coworking","cafe","epicerie","ecole","autre"]'::jsonb,'Monter une pergola bioclimatique','1 journée','3–6 pers.','+7 pts adaptation · −30 % ensoleillement',18)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('rafraichissement-passif-du-bati','Rafraîchissement passif du bâti','adaptation','moyen','❄️',null,'Combiner protections solaires (volets, brise-soleil), ventilation nocturne traversante et inertie thermique pour rafraîchir le bâtiment sans climatisation. Un puits canadien (échangeur air-sol) pré-rafraîchit l''air entrant de 4 à 8 °C. Le confort d''été est assuré avec une consommation énergétique quasi nulle, même par +2 °C.','−4 à −6 °C sans clim','2 000–12 000 €',0.4,85,'["Jusqu''à −6 °C en intérieur sans climatisation","Consommation énergétique quasi nulle","Confort d''été durable face aux canicules"]'::jsonb,'["Température intérieure évitée °C","Énergie de clim économisée kWh/an"]'::jsonb,'["ESRS E1"]'::jsonb,'Confort d''été passif, réduit le besoin de climatisation (E1).','["ecolieu","habitat","tiers","fablab","coworking","incubateur","ecole","autre"]'::jsonb,'Audit & rafraîchissement passif','2 jours','3–5 pers.','+12 pts adaptation · −5 °C sans clim',19)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();
insert into public.biblio_solutions (id,nom,cat,cplx,img,photo,description,impact,budget,co2,graines,avantages,indicateurs_libres,esrs,esrs_detail,lieux,quete_titre,quete_duree,quete_nb,quete_impact,ordre)
  values ('desimpermeabilisation-des-sols','Désimperméabilisation des sols','adaptation','moyen','💦',null,'Remplacer le bitume et le béton par des sols perméables et végétalisés (stabilisé clair, dalles engazonnées, noues plantées). Les surfaces claires et vivantes stockent moins de chaleur, laissent l''eau s''infiltrer et rafraîchissent l''air par évaporation. Lutte directement contre l''effet d''îlot de chaleur et contre les inondations lors des orages intenses.','−2 °C en surface','40–120 €/m²',0.3,60,'["Réduit l''effet d''îlot de chaleur urbain","Infiltre l''eau de pluie et recharge les nappes","Rafraîchit l''air ambiant par évaporation"]'::jsonb,'["Surface désimperméabilisée m²","Eau infiltrée L/an"]'::jsonb,'["ESRS E1","ESRS E3"]'::jsonb,'Adaptation aux chaleurs et aux pluies intenses (E1), gestion de l''eau (E3).','["ecolieu","habitat","tiers","jardin","ecole","autre"]'::jsonb,'Désimperméabiliser une cour','2 week-ends','5–10 pers.','+8 pts adaptation · sol perméable',20)
  on conflict (id) do update set nom=excluded.nom,cat=excluded.cat,cplx=excluded.cplx,img=excluded.img,photo=excluded.photo,description=excluded.description,impact=excluded.impact,budget=excluded.budget,co2=excluded.co2,graines=excluded.graines,avantages=excluded.avantages,indicateurs_libres=excluded.indicateurs_libres,esrs=excluded.esrs,esrs_detail=excluded.esrs_detail,lieux=excluded.lieux,quete_titre=excluded.quete_titre,quete_duree=excluded.quete_duree,quete_nb=excluded.quete_nb,quete_impact=excluded.quete_impact,ordre=excluded.ordre, updated_at=now();

insert into public.biblio_indicateurs (id,nom,livre,unite,point0,point100,poids,description,photo,solution_noms,odd,esrs,vsme,ordre)
  values ('eco_co2','Émissions de CO₂ évitées','ecologie','kg CO₂e/an',0,8000,1,'Le carbone que le lieu n''émet plus grâce à ses solutions : énergie renouvelable, sobriété du bâti, circuits courts et réemploi. C''est l''indicateur climat de référence.','https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=800&q=80&auto=format&fit=crop','["Panneaux solaires PV","Récupération eau de pluie","Compostage partagé","Réemploi matériaux","Isolation paille","Chauffe-eau solaire","Rafraîchissement passif du bâti"]'::jsonb,'[7,13]'::jsonb,'["E1"]'::jsonb,'["B3 · Énergie & GES"]'::jsonb,1)
